// The A11-shaped change oracle: names whose declared RETURN type moves between
// two adjacent supported minors, keyed to the minor it moved AT. A project whose
// declared PhpTarget is not wholly at or above that minor declines the row; an
// unknown target admits (the row is Asserted anyway, ADR-0069 §3).
//
// Listed independently of the table above: a name can be version-sensitive
// without carrying an admitted row, and the gate must stay complete either way.
// Sorted by key for binary search.

pub(crate) static RETURN_VERSION_SENSITIVE: &[(&str, (u16, u16))] = &[
    ("gc_status", (8, 3)),
    ("opcache_get_configuration", (8, 3)),
    ("session_get_cookie_params", (8, 5)),
    ("str_split", (8, 2)),
];
